<body>
    <div id="content">
        <div class="loading">正在加载环境数据...</div>
    </div>

    <script>
        /* ========== 获取消息内容 ========== */
        function getMessageData() {
            var chatMessages = getChatMessages(getCurrentMessageId());
            if (!chatMessages || chatMessages.length === 0) {
                return null;
            }
            return chatMessages[0].message;
        }

        /* ========== 解析数据 ========== */
        function parseData(messageText) {
            var result = {};
            var tagMatch = messageText.match(/<location_card>([\s\S]*?)<\/location_card>/);

            if (!tagMatch || !tagMatch[1]) {
                return result;
            }

            var content = tagMatch[1];
            var regex = /\[(.*?)\|(.*?)\]/g;
            var match;

            while ((match = regex.exec(content)) !== null) {
                if (match.length >= 3) {
                    var key = match[1].trim();
                    var value = match[2].trim();
                    result[key] = value;
                }
            }
            return result;
        }

        /* ========== 渲染界面 ========== */
        function renderPage(data) {
            if (Object.keys(data).length === 0) {
                document.getElementById('content').innerHTML = '<div class="loading">解析环境数据失败</div>';
                return;
            }

            /* 判断所属势力，分配主题样式 */
            var faction = data['势力'] || '';
            var themeClass = 'theme-default';

            if (faction.includes('帝国') || faction.includes('奥尔德南')) themeClass = 'theme-empire';
            else if (faction.includes('王国') || faction.includes('阿尔比恩')) themeClass = 'theme-kingdom';
            else if (faction.includes('多尔海姆') || faction.includes('矮人')) themeClass = 'theme-dwarf';
            else if (faction.includes('乌尔加特') || faction.includes('兽人')) themeClass = 'theme-orc';
            else if (faction.includes('希尔凡蒂尔') || faction.includes('精灵')) themeClass = 'theme-elf';
            else if (faction.includes('艾瑟尔') || faction.includes('翼民')) themeClass = 'theme-bird';
            else if (faction.includes('涅瑞廷') || faction.includes('海妖')) themeClass = 'theme-sea';
            else if (faction.includes('尼弗海姆') || faction.includes('龙裔')) themeClass = 'theme-dragon';
            else if (faction.includes('莫尔加纳') || faction.includes('黯渊') || faction.includes('潮息')) themeClass = 'theme-abyss';
            else if (faction.includes('乌尔坎') || faction.includes('蜥蜴种') || faction.includes('泥心城')) themeClass = 'theme-newworld';
            else if (faction.includes('城邦') || faction.includes('卡兰蒂亚')) themeClass = 'theme-default';

            /* 处理风险等级样式 */
            var riskText = data['风险'] || '未知';
            var riskClass = 'risk-safe';
            if (riskText.includes('警惕') || riskText.includes('警告') || riskText.includes('中危')) {
                riskClass = 'risk-warn';
            } else if (riskText.includes('危险') || riskText.includes('致命') || riskText.includes('高危')) {
                riskClass = 'risk-danger';
            }

            /* 处理可互动标签（纯文本展示，无点击事件） */
            var interactHtml = '';
            if (data['可互动'] && data['可互动'] !== '无' && data['可互动'] !== '暂无') {
                var items = data['可互动'].split(/[，,、]/);
                var tagsHtml = items.map(function(item) {
                    var cleanItem = item.trim();
                    if (!cleanItem) return '';
                    return '<div class="interact-tag">' + cleanItem + '</div>';
                }).join('');

                if (tagsHtml) {
                    interactHtml =
                        '<div class="interact-section">' +
                            '<div class="interact-label">🔍 视野内目标：</div>' +
                            '<div class="interact-tags">' + tagsHtml + '</div>' +
                        '</div>';
                }
            }

            /* 构建完整HTML */
            var html =
                '<div class="loc-card ' + themeClass + '">' +
                    '<div class="loc-header">' +
                        '<div class="loc-title">' +
                            '<div class="loc-region">' + (data['区域'] || '未知区域') + '</div>' +
                            '<div class="loc-faction">所属势力：' + (data['势力'] || '无') + '</div>' +
                        '</div>' +
                        '<div class="loc-risk ' + riskClass + '">' + riskText + '</div>' +
                    '</div>' +

                    '<div class="loc-body">' +
                        '<div class="loc-status-row">' +
                            '<div class="status-item">' +
                                '<div class="status-label">天气</div>' +
                                '<div class="status-value">' + (data['天气'] || '--') + '</div>' +
                            '</div>' +
                            '<div class="status-item">' +
                                '<div class="status-label">时段</div>' +
                                '<div class="status-value">' + (data['时段'] || '--') + '</div>' +
                            '</div>' +
                            '<div class="status-item">' +
                                '<div class="status-label">氛围</div>' +
                                '<div class="status-value">' + (data['氛围'] || '--') + '</div>' +
                            '</div>' +
                        '</div>' +

                        '<div class="detail-grid">' +
                            '<div class="detail-label">声景</div>' +
                            '<div class="detail-value">' + (data['声景'] || '寂静无声') + '</div>' +

                            '<div class="detail-label">气息</div>' +
                            '<div class="detail-value">' + (data['气息'] || '没有特殊气味') + '</div>' +

                            '<div class="detail-label">人群</div>' +
                            '<div class="detail-value">' + (data['人群'] || '空无一人') + '</div>' +

                            '<div class="detail-label">地标</div>' +
                            '<div class="detail-value">' + (data['地标'] || '无明显地标') + '</div>' +
                        '</div>' +

                        interactHtml +
                    '</div>' +
                '</div>';

            document.getElementById('content').innerHTML = html;
        }

        /* ========== 主函数 ========== */
        function init() {
            try {
                var messageText = getMessageData();
                if (!messageText) return;
                var data = parseData(messageText);
                renderPage(data);
            } catch (error) {
                console.error("环境卡片渲染错误:", error);
            }
        }

        $(function() { init(); });
    </script>
</body>
</html>
